package games.brennan.dungeontrain.client.chat.emoji;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.mojang.logging.LogUtils;
import org.jetbrains.annotations.Nullable;
import org.slf4j.Logger;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * The bundled Twemoji index ({@code assets/dungeontrain/emoji/index.json}, generated by
 * {@code scripts/emoji/build-emoji-font.py}): which emoji sequence draws as which character of the
 * {@code dungeontrain:emoji} font, and which {@code :shortcode:} names which emoji.
 *
 * <p>Sequences are keyed with every U+FE0F (the emoji variation selector) removed, so {@code ❤️} and
 * {@code ❤} find the same glyph. Single characters whose default presentation is text (©, ❤, ↔, ⚠ …)
 * only match when the text itself carried the selector, so ordinary symbols in chat and in UI strings
 * keep their plain glyph — the same rule Discord applies.</p>
 *
 * <p>Pure lookup, no Minecraft classes: loaded from the class path once, shared, read-only.</p>
 */
public final class EmojiIndex {

    private static final Logger LOGGER = LogUtils.getLogger();
    private static final String RESOURCE = "/assets/dungeontrain/emoji/index.json";
    static final int FE0F = 0xFE0F;

    private static volatile EmojiIndex shared;

    private final Map<String, Integer> glyphs;
    private final Set<String> textDefault;
    private final Map<String, String> shortcodes;
    private final Map<Integer, Integer> maxLenByFirst;

    EmojiIndex(Map<String, Integer> glyphs, Set<String> textDefault, Map<String, String> shortcodes) {
        this.glyphs = Map.copyOf(glyphs);
        this.textDefault = Set.copyOf(textDefault);
        this.shortcodes = Map.copyOf(shortcodes);
        Map<Integer, Integer> max = new HashMap<>();
        for (String key : glyphs.keySet()) {
            int[] cps = parseKey(key);
            max.merge(cps[0], cps.length, Math::max);
        }
        this.maxLenByFirst = Map.copyOf(max);
    }

    /** The shared index, loaded on first use; an empty index if the resource is missing or broken. */
    public static EmojiIndex get() {
        EmojiIndex i = shared;
        if (i == null) {
            synchronized (EmojiIndex.class) {
                i = shared;
                if (i == null) {
                    i = load();
                    shared = i;
                }
            }
        }
        return i;
    }

    private static EmojiIndex load() {
        try (InputStream in = EmojiIndex.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                LOGGER.warn("[DungeonTrain] emoji index {} missing; emoji will draw as plain text", RESOURCE);
                return new EmojiIndex(Map.of(), Set.of(), Map.of());
            }
            try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
                return parse(JsonParser.parseReader(r).getAsJsonObject());
            }
        } catch (Exception e) {
            LOGGER.warn("[DungeonTrain] emoji index unreadable; emoji will draw as plain text", e);
            return new EmojiIndex(Map.of(), Set.of(), Map.of());
        }
    }

    static EmojiIndex parse(JsonObject root) {
        Map<String, Integer> glyphs = new HashMap<>();
        for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("emoji").entrySet()) {
            glyphs.put(normalize(e.getKey()), Integer.parseInt(e.getValue().getAsString(), 16));
        }
        Set<String> textDefault = new HashSet<>();
        if (root.has("textDefault")) {
            for (JsonElement e : root.getAsJsonArray("textDefault")) textDefault.add(normalize(e.getAsString()));
        }
        Map<String, String> shortcodes = new HashMap<>();
        if (root.has("shortcodes")) {
            for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("shortcodes").entrySet()) {
                shortcodes.put(e.getKey(), normalize(e.getValue().getAsString()));
            }
        }
        return new EmojiIndex(glyphs, textDefault, shortcodes);
    }

    /** One emoji found in text: the font character to draw, and how many UTF-16 chars it replaces. */
    public record Match(int glyph, int length) {}

    /**
     * The longest emoji starting at {@code start} in {@code text}, or null. With {@code force} a
     * text-presentation symbol matches without its selector (reaction names, which are always emoji).
     */
    @Nullable
    public Match match(String text, int start, boolean force) {
        int first = text.codePointAt(start);
        Integer maxLen = maxLenByFirst.get(first);
        if (maxLen == null) return null;
        int[] cps = new int[maxLen];
        int[] ends = new int[maxLen];
        int n = 0;
        int i = start;
        boolean selectorAfterFirst = false;
        while (i < text.length() && n < maxLen) {
            int cp = text.codePointAt(i);
            i += Character.charCount(cp);
            if (cp == FE0F) {
                if (n == 0) break;
                if (n == 1) selectorAfterFirst = true;
                ends[n - 1] = i; // a trailing selector belongs to the emoji before it
                continue;
            }
            cps[n] = cp;
            ends[n] = i;
            n++;
        }
        for (int len = n; len >= 1; len--) {
            String key = key(cps, len);
            Integer glyph = glyphs.get(key);
            if (glyph == null) continue;
            if (len == 1 && !force && !selectorAfterFirst && textDefault.contains(key)) continue;
            int end = ends[len - 1];
            // Swallow a selector right after the match too (it was not reached if the loop stopped).
            if (end < text.length() && text.codePointAt(end) == FE0F) end += 1;
            return new Match(glyph, end - start);
        }
        return null;
    }

    /** The emoji a {@code :shortcode:} name stands for (without colons), or null. */
    @Nullable
    public String shortcode(String name) {
        String key = shortcodes.get(name.toLowerCase(java.util.Locale.ROOT));
        if (key == null) return null;
        StringBuilder sb = new StringBuilder();
        for (int cp : parseKey(key)) sb.appendCodePoint(cp);
        return sb.toString();
    }

    public boolean isEmpty() {
        return glyphs.isEmpty();
    }

    static String normalize(String hexKey) {
        StringBuilder sb = new StringBuilder();
        for (String part : hexKey.toLowerCase(java.util.Locale.ROOT).split("-")) {
            if (part.isEmpty()) continue;
            int cp = Integer.parseInt(part, 16);
            if (cp == FE0F) continue;
            if (!sb.isEmpty()) sb.append('-');
            sb.append(Integer.toHexString(cp));
        }
        return sb.toString();
    }

    private static String key(int[] cps, int len) {
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < len; k++) {
            if (k > 0) sb.append('-');
            sb.append(Integer.toHexString(cps[k]));
        }
        return sb.toString();
    }

    private static int[] parseKey(String key) {
        String[] parts = key.split("-");
        int[] out = new int[parts.length];
        for (int k = 0; k < parts.length; k++) out[k] = Integer.parseInt(parts[k], 16);
        return out;
    }
}
